'use strict';

// MODULES //

import numelDimension from '@stdlib/ndarray-base-numel-dimension';
import getStride from '@stdlib/ndarray-base-stride';
import getOffset from '@stdlib/ndarray-base-offset';
import getData from '@stdlib/ndarray-base-data-buffer';
import ndarraylike2scalar from '@stdlib/ndarray-base-ndarraylike2scalar';
import clipIndex from '@stdlib/ndarray-base-clip-index';
import { ndarray as strided } from '@stdlib/blas-ext-base-sindex-of-not-equal';


// MAIN //

/**
* Returns the first index of an element in a one-dimensional single-precision floating-point ndarray which is not equal to a specified search element.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray containing the search element.
*     -   a zero-dimensional ndarray containing the index from which to begin searching.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {integer} index
*
* @example
* import Float32Vector from '@stdlib/ndarray-vector-float32';
* import scalar2ndarray from '@stdlib/ndarray-from-scalar';
*
* var x = new Float32Vector( [ 1.0, 1.0, 3.0 ] );
*
* var searchElement = scalar2ndarray( 1.0, {
*     'dtype': 'float32'
* });
*
* var fromIndex = scalar2ndarray( 0, {
*     'dtype': 'generic'
* });
*
* var v = sindexOfNotEqual( [ x, searchElement, fromIndex ] );
* // returns 2
*/
function sindexOfNotEqual( arrays ) {
	var searchElement;
	var fromIndex;
	var stride;
	var offset;
	var idx;
	var N;
	var x;

	x = arrays[ 0 ];
	searchElement = ndarraylike2scalar( arrays[ 1 ] );
	fromIndex = ndarraylike2scalar( arrays[ 2 ] );

	N = numelDimension( x, 0 );
	fromIndex = clipIndex( fromIndex, N );
	if ( fromIndex >= N ) {
		return -1;
	}
	N -= fromIndex;

	stride = getStride( x, 0 );
	offset = getOffset( x ) + ( stride*fromIndex );

	idx = strided( N, searchElement, getData( x ), stride, offset );
	if ( idx >= 0 ) {
		idx += fromIndex;
	}
	return idx;
}


// EXPORTS //

export default sindexOfNotEqual;
